BEGIN;
CREATE TABLE knowledge_ingestion_job(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,job_id uuid NOT NULL,asset_id uuid NOT NULL,asset_version_id uuid NOT NULL,request_id uuid NOT NULL,trace_id text,policy_version text NOT NULL,parser_profile text NOT NULL,parser_version text NOT NULL,original_checksum text NOT NULL CHECK(original_checksum~'^sha256:[a-f0-9]{64}$'),fencing_token bigint NOT NULL CHECK(fencing_token>0),state text NOT NULL CHECK(state IN('queued','running','retry_wait','succeeded','failed','quarantined','cancelled')),attempt integer NOT NULL DEFAULT 0 CHECK(attempt BETWEEN 0 AND 3),error_code text,error_message text CHECK(char_length(error_message)<=256),normalized_checksum text CHECK(normalized_checksum~'^sha256:[a-f0-9]{64}$'),artifact_key text,artifact_size_bytes bigint CHECK(artifact_size_bytes BETWEEN 0 AND 52428800),language text CHECK(char_length(language) BETWEEN 2 AND 16),unit_count integer CHECK(unit_count>=0),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,workspace_id,job_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,asset_version_id)REFERENCES knowledge_asset_version(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT,UNIQUE(tenant_id,workspace_id,asset_version_id,parser_profile,parser_version),CHECK((state='succeeded')=(normalized_checksum IS NOT NULL AND artifact_key IS NOT NULL AND artifact_size_bytes IS NOT NULL)));
CREATE TABLE knowledge_ingestion_outbox(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,event_id uuid NOT NULL,event_type text NOT NULL CHECK(event_type IN('knowledge.ingestion.queued.v1','knowledge.ingestion.started.v1','knowledge.ingestion.retry_scheduled.v1','knowledge.ingestion.succeeded.v1','knowledge.ingestion.failed.v1','knowledge.ingestion.quarantined.v1')),request_id uuid NOT NULL,job_id uuid NOT NULL,asset_id uuid NOT NULL,asset_version_id uuid NOT NULL,parser_version text NOT NULL,state text NOT NULL,error_code text,original_checksum text NOT NULL,normalized_checksum text,occurred_at timestamptz NOT NULL,published_at timestamptz,PRIMARY KEY(tenant_id,workspace_id,event_id),FOREIGN KEY(tenant_id,workspace_id,job_id)REFERENCES knowledge_ingestion_job(tenant_id,workspace_id,job_id)ON DELETE RESTRICT);
REVOKE ALL ON knowledge_ingestion_job,knowledge_ingestion_outbox FROM PUBLIC;GRANT SELECT,INSERT,UPDATE(state,attempt,error_code,error_message,normalized_checksum,artifact_key,artifact_size_bytes,language,unit_count,updated_at)ON knowledge_ingestion_job TO domus_knowledge_runtime;GRANT SELECT,INSERT ON knowledge_ingestion_outbox TO domus_knowledge_runtime;
ALTER TABLE knowledge_ingestion_job ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_ingestion_job FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_ingestion_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_ingestion_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY knowledge_ingestion_job_scope ON knowledge_ingestion_job TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY knowledge_ingestion_outbox_scope ON knowledge_ingestion_outbox TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
INSERT INTO schema_migrations(version,description)VALUES(14,'V1-404 deterministic ingestion parsing and normalization')ON CONFLICT(version)DO NOTHING;COMMIT;
